"""Native printed exercise 26–28; SpaceBook answers are separate additions."""
from html import escape
MCQS=[]
def mcq(n,q,opts,ans,why):MCQS.append({'qNo':n,'q':q,'opts':opts,'ans':ans,'explanation':why,'sourceReferences':[{'printedPage':26 if len(MCQS)<7 else 27}],'solutionOrigin':'SpaceBook learning answer'})
mcq('i','The wall of the trachea (windpipe) and bronchi of man is furnished with a series of incomplete:',['cartilaginous plates','chitinous rings','cartilaginous rings','muscular rings'],2,'Incomplete cartilaginous rings support the trachea and the larger bronchi while keeping their lumen open. Smaller bronchi have cartilage plates.')
mcq('ii','What does not happen during inspiration in man?',['intercostals muscles contract','ribs are elevated','diaphragm becomes dome-shaped','ribs move forwards'],2,'During inspiration the diaphragm contracts and flattens. Its dome-shaped relaxed position is associated with expiration.')
mcq('iii','The lateral walls of the chest cavity of man are composed of the:',['ribs','intercostals muscles','ribs & Intercostals muscles','ribs, Intercostals muscles & diaphragm'],2,'The ribs and intercostal muscles form the side walls. The diaphragm forms the floor rather than the lateral walls.')
mcq('iv','When the human blood leaves the capillary bed of the tissue, most of the carbon dioxide is in the form of:',['carbonic acid','bicarbonate ions','carboxylic acid','none of them'],1,'The textbook assigns about 70% of carbon dioxide transport to bicarbonate ions, the largest fraction.')
mcq('v','Which sequence of organs is correct in air passageway of man?',['nasal cavities larynx pharynx trachea bronchi','nasal cavities pharynx trachea larynx bronchi','nasal cavities pharynx larynx bronchi trachea','nasal cavities pharynx larynx trachea bronchi'],3,'Air passes from the nasal cavities to the pharynx, larynx, trachea and then the bronchi.')
mcq('vi','Which part of the air passage way possesses cartilage plates in its wall?',['bronchioles','distal region of bronchi','proximal region of bronchi','trachea'],1,'Cartilage is arranged as plates in the smaller, more distal bronchi. The trachea and proximal bronchi have ring supports; bronchioles lack cartilage.')
mcq('vii','Human lungs are spongy due to the presence of million of:',['bronchi','alveoli','bronchioles','trachea'],1,'The numerous small air sacs, alveoli, contribute to the spongy structure of lung tissue.')
mcq('viii','Which event is not associated with the activity of expiration?',['contraction of diaphragm','more dome like shape of diaphragm','back ward & down ward movement of rib cage','relaxation of intercostals muscles'],0,'Quiet expiration follows relaxation of the diaphragm and intercostal muscles. Diaphragm contraction initiates inspiration.')
mcq('ix','Oxygen carrying capacity of blood does not depend upon:',['partial pressure of CO₂','partial pressure of O₂','height from sea level','quantity of blood'],3,'For carrying capacity expressed per fixed blood volume, the total quantity of blood is not the determining factor. Oxygen pressure, altitude and carbon-dioxide-related changes affect loading; haemoglobin concentration also matters.')
mcq('x','When haemoglobin of the blood is fully saturated with oxygen, the 100cc of blood contains.',['15cc of oxygen','20cc of oxygen','25cc of oxygen','10cc of oxygen'],1,'The textbook gives a maximum of about 20 ml oxygen per 100 ml blood; 1 cc equals 1 ml.')
def solved(n,q,steps,answer):
 html='<div><strong>SpaceBook learning answer</strong><ol>'
 for i,step in enumerate(steps):html+=f'<li data-example-step="{i}" style="'+('display:none;' if i else '')+'">'+escape(step)+'</li>'
 html+='</ol><button type="button" data-revealed="1" onclick="revealMathExampleStep(this)">Next step</button> <button type="button" onclick="resetMathExampleSteps(this)">Start again</button></div>'
 html+='<div data-example-answer style="display:none;margin-top:.7rem;"><strong>Answer: </strong>'+escape(answer)+'</div>'
 return {'qNo':n,'q':q,'steps':steps,'answer':html,'plainAnswer':answer,'solutionOrigin':'SpaceBook learning answer','sourceReferences':[{'printedPage':27}]}
SHORT=[
solved('i','What are the risk factors and causes of TB?',['Identify the cause: infection with Mycobacterium tuberculosis.','Explain transmission: infectious airborne droplets can pass between people, especially during close or prolonged contact.','List risk factors from the chapter: HIV or weakened immunity, poverty, crowded housing, homelessness, alcoholism, migration from a country with many cases, and health-care exposure.'],'TB is caused by M. tuberculosis; close exposure and conditions that increase exposure or weaken immunity raise the risk.'),
solved('ii','State the signs and symptoms of otitis media.',['Start with the ear symptoms: sudden severe earache, hearing loss, tinnitus and fullness in the ear.','Add the general symptoms: irritability, fever, headache, appetite or sleeping changes and nausea.','Include fluid discharge and difficulty speaking or hearing; a ruptured eardrum may discharge pus and reduce pain.'],'Ear pain, hearing disturbance, fullness, fever or irritability and possible ear discharge are the listed signs and symptoms.'),
solved('iii','List two differences between haemoglobin and myoglobin.',['Compare location: haemoglobin is in red blood cells; myoglobin is in muscle cells.','Compare function: haemoglobin transports oxygen in blood; myoglobin stores oxygen in muscles and releases it when needed.'],'Haemoglobin: red blood cells and oxygen transport. Myoglobin: muscle cells and oxygen storage.'),
solved('iv','Give any two factors that affect the oxygen carrying capacity of blood.',['Choose haemoglobin concentration: more functioning haemoglobin per fixed blood volume provides more oxygen-binding sites.','Choose oxygen partial pressure: it affects haemoglobin oxygen loading and saturation.','Distinguish maximum capacity from the oxygen actually carried at a particular saturation.'],'Haemoglobin concentration and oxygen partial pressure affect oxygen carriage.')]
LONG=[
solved('i','Describe the structure of human respiratory system.',['Follow the air path: nostrils and nasal cavities → pharynx → larynx → trachea → bronchi → bronchioles → alveoli.','Describe the nose: hairs, mucus and cilia filter air; a blood supply warms it and mucus moistens it.','Describe the conducting passages: pharynx is shared with the digestive tract; the larynx has vocal cords; cartilage supports the trachea and bronchi.','Describe the branching passages: two bronchi enter the lungs, divide repeatedly and form bronchioles, which lack cartilage and open into alveoli.','Describe the exchange surfaces: thin moist alveolar epithelium, capillary networks and a large area support diffusion; elastic fibres allow expansion and recoil.','Locate the lungs: the right has three lobes, the left two; pleural membranes surround them and their bases rest on the diaphragm.'],'The respiratory system combines conducting air passages with alveolar gas-exchange surfaces inside the paired lungs.'),
solved('ii','Describe the mechanism of breathing in man.',['Identify the control system: medullary respiratory centres send rhythmic signals through intercostal and phrenic nerves.','In inspiration the external intercostal muscles contract and the ribs move upward and outward; the diaphragm contracts and flattens.','Thoracic volume increases, pressure in the lungs falls below atmospheric pressure, and air enters through the air passages.','During quiet expiration the muscles relax; the diaphragm becomes dome-shaped and the ribs move down and inward.','Elastic recoil reduces lung volume, pressure rises, and air flows outward; forced expiration recruits additional muscular effort.'],'Breathing alternates pressure changes produced by ribs, respiratory muscles and diaphragm, causing air to move into and out of the lungs.'),
solved('iii','Describe the role of respiratory pigments in transport and storage of respiratory gases.',['Define respiratory pigments as molecules involved in respiratory-gas transport or storage.','Explain haemoglobin: its iron-containing haem groups bind oxygen reversibly; one molecule can bind four oxygen molecules.','High oxygen partial pressure in the lungs favours loading, while tissue conditions favour unloading.','Explain carbon-dioxide carriage: some binds to globin as carbaminohaemoglobin; most is carried as bicarbonate, and haemoglobin helps buffer hydrogen ions.','Explain myoglobin: it binds and stores oxygen in muscle cells, making oxygen available during demand.','Give other source examples: haemocyanin in molluscs, haemoerythrin in some marine animals and chlorocruorin in annelids.'],'Haemoglobin chiefly transports oxygen in blood and assists carbon-dioxide transport and buffering; myoglobin supplies muscle oxygen storage.'),
solved('iv','State the causes, symptoms, and treatment of any one disorder of lower respiratory tract.',['Choose the textbook example pneumonia and define it as inflammation with fluid or pus in alveolar sacs.','State causes from the chapter: bacterial infection, including mycoplasma, or viral infection.','State symptoms: cough, fever, chest pain, breathing difficulty and weakness; exact combinations vary with the agent.','Describe textbook treatment generally: treatment depends on severity and the infecting organism; antibacterial medicines address bacterial infection.','State complications listed in the chapter: pleural effusion, empyema, hyponatraemia and rarely lung abscess.'],'Pneumonia is the chosen lower-tract disorder; its cause and clinical severity determine treatment.')]
CONNECTIONS=[
('Describe the development and working of artificial breathing apparatus (for use under water and at high altitude and by fireman)','Compare three needs: an underwater diver needs a gas supply delivered at ambient pressure; high-altitude oxygen equipment supplements oxygen where atmospheric oxygen pressure is lower; firefighters use a self-contained supply isolated from smoke. A cylinder, regulator and suitable mask or mouthpiece deliver breathing gas; valves manage inhalation and exhalation. Historical development progressed from external air supplies to portable regulated supplies.','مصنوعی تنفسی آلات کے لیے غوطہ خور، بلند مقام پر کام کرنے والے اور آگ بجھانے والے کی ضروریات کا موازنہ کریں؛ سلنڈر، ریگولیٹر اور ماسک یا ماؤتھ پیس محفوظ تنفسی گیس پہنچاتے ہیں۔','د مصنوعي تنفس په وسایلو کې د غوطه وهونکي، د لوړ ځای د کارکوونکي او اور وژونکي اړتیاوې پرتله کړئ؛ سلنډر، تنظیموونکی او ماسک یا د خولې برخه تنفسي ګاز برابروي.'),
('Justify why birds perform much better than man at high altitude.','Bird air sacs support largely one-way airflow through the gas-exchanging lung passages, so relatively fresh air passes through during both phases of ventilation. Their respiratory arrangement is efficient at extracting oxygen when its partial pressure is low; high-altitude bird adaptations vary between species.','پرندوں کے ہوائی تھیلے پھیپھڑوں میں زیادہ تر یک طرفہ ہوا کا بہاؤ قائم رکھتے ہیں، اس لیے کم جزوی دباؤ پر بھی آکسیجن حاصل کرنے میں ان کا نظام مؤثر ہے۔','د مرغانو هوایي کڅوړې د سږو په لارو کې تر ډېره یو طرفه هوايي جریان ساتي، نو د اکسیجن په کم جزوي فشار کې هم د هغوی تنفسي نظام اغېزمن دی.'),
('Describe the purpose of mouth to mouth method for artificial respiration in First Aid.','Its purpose is artificial ventilation: delivering air to a person who cannot breathe adequately, so oxygen can reach the lungs and carbon dioxide can be removed. This describes the physiological purpose, rather than a first-aid procedure.','اس کا مقصد مصنوعی ہوا رسانی ہے تاکہ خود کافی سانس نہ لینے والے شخص کے پھیپھڑوں تک آکسیجن پہنچے اور کاربن ڈائی آکسائیڈ نکل سکے۔','موخه یې مصنوعي هوا ورکول دي، څو هغه شخص چې پخپله کافي ساه نه شي اخیستلای، سږو ته یې اکسیجن ورسېږي او کاربن ډای اکسایډ ووځي.'),
('Relate the transportation of gases to hiccup, sneezing, and snoring.','Hiccup is a sudden involuntary diaphragm contraction followed by closure at the glottis, interrupting airflow. Sneezing forcefully expels air through upper passages to clear irritation. Snoring results from vibration of partially obstructed upper-airway tissues during airflow. These alter ventilation or airflow; they are not separate chemical gas-transport mechanisms.','ہچکی ہوا کے بہاؤ کو اچانک بدلتی ہے، چھینک اوپری گزرگاہوں سے ہوا زور سے نکالتی ہے، اور خراٹوں میں تنگ گزرگاہ کے بافت ہوا کے ساتھ لرزتے ہیں۔','هچکۍ د هوا جریان ناڅاپه بدلوي، پرنجی له پاسنیو لارو هوا په زور باسي، او په خرېدا کې د تنګې هوايي لارې نسجونه له هوا سره رپېږي.'),
('Describe the carbon monoxide poisoning (caused by gas heaters left on over-night in close environment).','Incomplete fuel combustion can produce carbon monoxide; inadequate ventilation allows it to accumulate. Carbon monoxide binds haemoglobin strongly, forming carboxyhaemoglobin and reducing oxygen delivery. This is different from carbaminohaemoglobin, the carbon-dioxide transport compound.','نامکمل احتراق سے کاربن مونو آکسائیڈ بن سکتی ہے جو کم ہوا داری میں جمع ہو کر ہیموگلوبن سے مضبوطی سے جڑتی ہے اور آکسیجن کی ترسیل کم کرتی ہے۔','د سون توکو نیمګړی سوځېدل کاربن مونو اکسایډ جوړولای شي چې په کمې هوا دارۍ کې راټولېږي، له هیموګلوبین سره کلک تړل کېږي او د اکسیجن رسونه کموي.')]
